import{displayName}from"#protocol/session-projection/display-name.js";import{AGENT_TOOL_NAME}from"#tools/framework/agent-contract.js";function withMoreCalls(e,t){return t<=1?e:`${e} +${String(t-1)} more`}function waitingOnTasks(e){let[t]=e;return e.length===1&&t!==AGENT_TOOL_NAME?`Waiting on ${displayName(t)}...`:e.length===1?`Waiting on a task...`:`Waiting on ${String(e.length)} tasks...`}function reviewingResults(e){let[t]=e;return t!=null&&t!==AGENT_TOOL_NAME&&e.every(e=>e===t)?`Reviewing ${displayName(t)}'s results...`:`Reviewing results...`}export{reviewingResults,waitingOnTasks,withMoreCalls};